import type { StepInput } from '../schema';
import type { LessonUpgrade } from './types';

// These small constructors keep the content readable; every task and explanation is lesson-specific.
const choice = (id: string, prompt: string, options: string[], answer: string, why: string): StepInput => ({
  kind: 'choice', id, prompt, before: '', after: '', options, answer, why,
});
const rewrite = (id: string, prompt: string, source: string, accept: string[], why: string): StepInput => ({
  kind: 'rewrite', id, prompt, source, accept, why, strict: true,
});
const cloze = (id: string, prompt: string, text: string, why: string, caps = false): StepInput => ({
  kind: 'cloze', id, prompt, text, why, caps,
});
const retrieve = (prompt: string, answer: string, why: string): StepInput => ({
  kind: 'type', id: 'transfer-zelfstandig-in-een-nieuwe-situatie', prompt,
  before: '', after: '', hint: '', answer, why,
});
const proofread = (
  id: string, prompt: string, text: string,
  corrections: Record<string, [string, string]>, traps: Record<string, string> = {},
): StepInput => ({
  kind: 'proofread', id, prompt, blind: true,
  intro: 'Zoek de fouten zelf, verbeter ze en laat correcte woorden staan. Lees daarna de hele tekst opnieuw.',
  tokens: text.split(/\s+/).map((t) => {
    const correction = corrections[t];
    return correction ? { t, fix: correction[0], why: correction[1] } : traps[t] ? { t, trap: traps[t] } : { t };
  }),
});

